/**
 * Validates a candidate chapter against all preceding chapters in the registry
 * to ensure that novelty, progression, and non-repetitive reasoning are preserved.
 */
export function validateChapterNovelty(
  candidate: Partial<ChapterIntellectualMetadata>,
  chapterNum: number
): { pass: boolean; score: number; warnings: string[]; insights: string[] } {
  const warnings: string[] = [];
  const insights: string[] = [];
  let score = 100;

  if (!candidate.centralQuestion || candidate.centralQuestion.trim().length < 15) {
    warnings.push('केन्द्रीय प्रश्न (Central Question) स्पष्ट र दार्शनिक रूपमा गहन छैन।');
    score -= 20;
  }

  if (!candidate.coreArgument || candidate.coreArgument.trim().length < 20) {
    warnings.push('मुख्य प्रतिपादन (Core Argument) स्पष्ट छैन।');
    score -= 20;
  }

  if (!candidate.uniquePerspective || candidate.uniquePerspective.trim().length < 20) {
    warnings.push('अद्वितीय दृष्टिकोण (Unique Perspective) स्पष्ट उल्लेख गरिएको छैन।');
    score -= 15;
  }

  // Compare candidate concepts with previous chapters
  const allPreviousConcepts: { ch: number; concept: string }[] = [];
  Object.entries(CHAPTER_METADATA_REGISTRY).forEach(([chStr, meta]) => {
    const ch = Number(chStr);
    if (ch < chapterNum) {
      meta.keyConcepts.forEach((concept) => {
        allPreviousConcepts.push({ ch, concept });
      });
    }
  });

  const candidateConcepts = candidate.keyConcepts || [];
  if (candidateConcepts.length === 0) {
    warnings.push('कम्तिमा ३ वटा नयाँ मुख्य अवधारणाहरू (Key Concepts) थप्नुहोस्।');
    score -= 15;
  }

  // Check for duplicate concepts
  candidateConcepts.forEach((c) => {
    const match = allPreviousConcepts.find(
      (p) => p.concept.toLowerCase().trim() === c.toLowerCase().trim()
    );
    if (match) {
      warnings.push(`अवधारणा "${c}" पहिले नै अध्याय ${match.ch} मा प्रयोग भइसकेको छ। यस अध्यायका लागि नयाँ विशिष्ट अवधारणा चयन गर्नुहोस्।`);
      score -= 10;
    }
  });

  // Check reasoning style
  if (!candidate.reasoningStyle) {
    warnings.push('यस अध्यायका लागि फरक तार्किक शैली (Reasoning Style) चयन गरिएको छैन।');
    score -= 10;
  } else {
    insights.push(`तार्किक शैली: ${candidate.reasoningStyle}`);
  }

  insights.push(`यस अध्यायको केन्द्रीय प्रश्नले पुस्तकको यात्रालाई अध्याय ${chapterNum - 1} बाट अगाडि बढाउँछ।`);

  return {
    pass: score >= 70 && warnings.length <= 1,
    score: Math.max(0, score),
    warnings,
    insights
  };
}
